create or replace function public.register_external_signed_contract(p_relationship_id uuid,p_signed_file_id uuid,p_terms_snapshot jsonb default '{}'::jsonb) returns public.contracts language plpgsql security definer set search_path='' as $$ declare r public.rental_relationships; f public.files; c public.contracts; v int; begin select * into r from public.rental_relationships where id=p_relationship_id; if not found then raise exception 'RENTAL_NOT_FOUND'; end if; if public.can_manage_administration(r.administration_id) is not true then raise exception 'MANAGEMENT_ACCESS_REQUIRED'; end if; select * into f from public.files where id=p_signed_file_id and administration_id=r.administration_id; if not found then raise exception 'SIGNED_FILE_NOT_FOUND'; end if; select coalesce(max(version_number),0)+1 into v from public.contracts where rental_relationship_id=r.id; insert into public.contracts(administration_id,rental_relationship_id,origin,status,version_number,signed_file_id,terms_snapshot,signed_at) values(r.administration_id,r.id,'EXTERNAL','SIGNED',v,p_signed_file_id,coalesce(p_terms_snapshot,'{}'::jsonb),now()) returning * into c; return c; end $$;
create or replace function public.register_habitex_generated_contract(p_relationship_id uuid,p_document_file_id uuid,p_document_hash text,p_terms_snapshot jsonb) returns public.contracts language plpgsql security definer set search_path='' as $$ declare r public.rental_relationships; f public.files; c public.contracts; v int; begin select * into r from public.rental_relationships where id=p_relationship_id; if not found then raise exception 'RENTAL_NOT_FOUND'; end if; if public.can_manage_administration(r.administration_id) is not true then raise exception 'MANAGEMENT_ACCESS_REQUIRED'; end if; select * into f from public.files where id=p_document_file_id and administration_id=r.administration_id; if not found then raise exception 'DOCUMENT_FILE_NOT_FOUND'; end if; if p_document_hash is null or p_document_hash !~ '^[A-Fa-f0-9]{64}$' then raise exception 'INVALID_DOCUMENT_HASH'; end if; select coalesce(max(version_number),0)+1 into v from public.contracts where rental_relationship_id=r.id; insert into public.contracts(administration_id,rental_relationship_id,origin,status,version_number,document_file_id,terms_snapshot,document_hash,generated_at) values(r.administration_id,r.id,'HABITEX','GENERATED',v,p_document_file_id,coalesce(p_terms_snapshot,'{}'::jsonb),lower(p_document_hash),now()) returning * into c; return c; end $$;
create or replace function public.attach_signed_contract_copy(p_contract_id uuid,p_signed_file_id uuid) returns public.contracts language plpgsql security definer set search_path='' as $$ declare c public.contracts; f public.files; begin select * into c from public.contracts where id=p_contract_id for update; if not found then raise exception 'CONTRACT_NOT_FOUND'; end if; if public.can_manage_administration(c.administration_id) is not true then raise exception 'MANAGEMENT_ACCESS_REQUIRED'; end if; if c.origin<>'HABITEX' or c.status not in('GENERATED','SHARED') then raise exception 'CONTRACT_NOT_SIGNABLE'; end if; select * into f from public.files where id=p_signed_file_id and administration_id=c.administration_id; if not found then raise exception 'SIGNED_FILE_NOT_FOUND'; end if; update public.contracts set signed_file_id=p_signed_file_id,status='SIGNED',signed_at=now() where id=c.id returning * into c; return c; end $$;
revoke all on function public.register_external_signed_contract(uuid,uuid,jsonb) from public,anon; revoke all on function public.register_habitex_generated_contract(uuid,uuid,text,jsonb) from public,anon; revoke all on function public.attach_signed_contract_copy(uuid,uuid) from public,anon; grant execute on function public.register_external_signed_contract(uuid,uuid,jsonb) to authenticated,service_role; grant execute on function public.register_habitex_generated_contract(uuid,uuid,text,jsonb) to authenticated,service_role; grant execute on function public.attach_signed_contract_copy(uuid,uuid) to authenticated,service_role;